// th16_s6_b12 - TH16 v1.00a Stage 6 BossCard7 ("裏・パーフェクトサマーアイス", Boss6 SUBSEASON=1).
// Source: st06bs.ecl.txt BossCard7 1915-2011; deps BossCard7_at 2013-2025,
// BossCard7_at2 2027-2106, BossCard7_at3 2108-2151, BossCard7_at4 2153-2195,
// BossCard7_at_f 2197-2253.
//
// Entry state (task): Boss6 has lifeSet(5000), position (0,128), zero velocity;
// SUBSEASON=1 selects this card. funcSet(2) is the approved omission
// (special-functions.md); the LIFE/TIME fallbacks below stay per source.
// The boss is invulnerable and takes no DPS, so LIFE stays 5000 and the
// 30/60/90s $TIME fallback drives the internal phases.
//
// $TIME is the enemy age, not this sub's script clock. Boss6 waits
// 200+30+30+60 = 320 frames before calling BossCard7 (st06bs:704-720), so the
// source $TIME at card entry is 320; we keep that offset instead of treating
// the sub entry as the timer origin.

const TIME_LIMIT: int = 7324;      // 120 shell buffer + 7200 source spell window + 4
const OPENING_BUFFER: int = 120;
const SRC_TIME_AT_ENTRY: int = 320;
const SRC_SPELL_ID: int = 94;
const TH16_SHARD: int = 512;       // source etSprite type 10
const TH16_BIG_BALL: int = 640;    // source etSprite type 18

// EX VELTIME (0x200000, a=60, r=difficulty speed, s=keep angle): scalar speed
// ramps linearly to target along the bullet's current direction.
xformdef VEL_RAMP(target: fx) {
    step_speed(target, 60 + 65536 * EASE_LINEAR);
}

// EX STEP (0x10, a=90, b=1, c=1): one 90-frame segment decelerating linearly
// to 0; at the segment boundary restore the target speed and re-aim at the
// player (c=1, r=0 offset).
xformdef STEP_AIM(target: fx) {
    step_speed(0fx, 90 + 65536 * EASE_LINEAR);
    wait(90);
    set_speed(target);
    aim_player(0deg);
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    spell_begin(0, SRC_SPELL_ID, pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    var life: int = spell_timer();
    _ = spawn_enemy(0fx, 128fx, 5000, 0, 0, 0, boss_main(life));
}

async sub boss_main(life: int) {
    set_invuln(65535);
    // 1956 movePosTime(60,4,0,128): entry is already (0,128), keep the verb.
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(90);                                  // 1961 +90: script time 90
    // 1963 moveLimit(0,128,256,192) omitted: the radius-96 orbit around (0,128)
    // spans exactly x[-96,96], y[32,224], i.e. it never crosses the clamp.
    // 1964 funcSet(2): approved omission. 1965 bombInvuln(0): no player bombs.
    var gen: int = 0;
    set_self_int(0, gen);
    spawn circle_task();                       // 1966 async id 1, never killed
    // 1971 LIFE>3500 && TIME<=30*60
    while SRC_TIME_AT_ENTRY + $self_age <= 1800 && $self_hp > 3500 { wait(1); }
    clear_bullets_at($self_x, $self_y, 640fx, 0);  // 1973 etClear(640)
    gen = gen + 1;
    set_self_int(0, gen);
    spawn at2(gen);                            // 1974 async id 2
    // 1979 LIFE>2500 && TIME<=60*60
    while SRC_TIME_AT_ENTRY + $self_age <= 3600 && $self_hp > 2500 { wait(1); }
    clear_bullets_at($self_x, $self_y, 640fx, 0);  // 1981
    gen = gen + 1;
    set_self_int(0, gen);                      // cancels the old at2 (killAsync 2)
    spawn at2(gen);                            // 1983
    spawn at3(gen);                            // 1984
    // 1989 LIFE>1500 && TIME<=90*60
    while SRC_TIME_AT_ENTRY + $self_age <= 5400 && $self_hp > 1500 { wait(1); }
    clear_bullets_at($self_x, $self_y, 640fx, 0);  // 1991
    gen = gen + 1;
    set_self_int(0, gen);                      // kills async 2/3/4
    spawn at2(gen);                            // 1995
    spawn at3(gen);                            // 1996
    spawn at4(gen);                            // 1997
    set_self_fx(0, 1fx);                       // 1998 %F0 = 1.0
    // 1999-2009: $A=10000 with wait(330), then wait(1000) forever; the source
    // card ends on the 7200-frame spell timeout. Run to the phase window, then
    // retreat naturally (owner gate stops the child tasks).
    while $self_age < life { wait(1); }
    gen = gen + 1;
    set_self_int(0, gen);
}

// 2013-2025 BossCard7_at: wait 60, spawn at_f, then orbit.
// 408 moveCircle(pi/2, 0.008726646, 0, 0): center = current position, theta=pi/2,
// omega=0.5 deg/frame. 409 moveCircleTime(300, keep, keep, 96, 0): radius
// interpolates 0 -> 96 over 300 movement ticks (mode sentinel -999999 treated as
// the default linear ramp), omega/d unchanged.
async sub circle_task() {
    wait(60);
    spawn at_f_task();                         // 2016 async, no user id
    var cx: fx = $self_x;                      // 408 hides the center here
    var cy: fx = $self_y;
    var theta: int = 16384;                    // pi/2 BAM
    var radius: fx = 0fx;
    var k: int = 0;
    var nx: fx = 0fx;
    var ny: fx = 0fx;
    loop {
        k = k + 1;
        if k <= 300 { radius = 96fx * (k as fx) / 300fx; } else { radius = 96fx; }
        theta = theta + 91;                    // 0.5 deg/frame = 91.02 BAM
        nx = cx + radius * cos(theta as angle);
        ny = cy + radius * sin(theta as angle);
        move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
        wait(1);
    }
}

// 2197-2253 BossCard7_at_f(10, 6, 3.883222): 60-frame wait, then a
// random-rotation ring (mode 3) of small shards from 48px, accelerating from 0.
async sub at_f_task() {
    wait(60);
    var rank: int = global(GVAR_RANK);
    var n: int = 11;                           // !E 5; !N 11; !H 11; !LO 11
    if rank == 0 { n = 5; }
    var target: fx = 3fx;                      // !E 3.0; !N 3.0; !H 3.5; !LO 4.0
    if rank == 2 { target = 3.5fx; }
    if rank >= 3 { target = 4fx; }
    var w: int = 10;                           // !E 10; !N 10; !H 9; !LO 8
    if rank == 2 { w = 9; }
    if rank >= 3 { w = 8; }
    sh_reset(0);
    sh_sprite(0, TH16_SHARD, 6);               // etSprite(0, 10, 6)
    sh_ring(0, 1);                             // etAim 3: fixed-direction ring
    sh_aim(0, 0);
    sh_count(0, n, 1);
    sh_speed(0, 0fx, 0fx);                     // etSpeed 0.0, 0.2; 1 layer -> 0.0
    sh_dist(0, 48fx);                          // etDist(0, 48)
    sh_xform(0, VEL_RAMP(target));             // VELTIME a=60
    _ = rand(65536);                           // 2230 %E = %RANDRAD (unused)
    var i: int = 0;
    var ra: int = 0;
    while i < 40000 {
        i = i + 1;
        ra = rand(65536) - 32768;              // RANDRAD, -pi..pi
        sh_angle(0, ra as angle, 0deg);        // etAngle(RANDRAD)
        sh_fire(0);
        wait(w);
    }
}

// 2027-2106 BossCard7_at2: two counter-rotating mode-3 rings per tick;
// Easy rotates B twice as fast and waits longer.
async sub at2(gen: int) {
    var rank: int = global(GVAR_RANK);
    var n: int = 4;                            // !E 4; !N 4; !H 5; !LO 6
    if rank == 2 { n = 5; }
    if rank >= 3 { n = 6; }
    var spd: fx = 2fx;                         // !E 2.0; !N 3.0; !H 3.2; !LO 3.5
    if rank == 1 { spd = 3fx; }
    if rank == 2 { spd = 3.2fx; }
    if rank >= 3 { spd = 3.5fx; }
    var w: int = 7;                            // !E 14; !N 7; !H 6; !LO 5
    if rank == 0 { w = 14; }
    if rank == 2 { w = 6; }
    if rank >= 3 { w = 5; }
    sh_reset(0);
    sh_sprite(0, TH16_SHARD, 6);               // etSprite(1, 10, 6)
    sh_ring(0, 1);                             // etAim 3
    sh_aim(0, 0);
    sh_count(0, n, 1);
    sh_speed(0, spd, 0fx);
    sh_dist(0, -0.4fx);                        // ANIM entry: -4 * initial speed 0.1
    var b: angle = 90deg;                      // %B
    var c: angle = 90deg;                      // %C
    var i: int = 0;
    var k: int = 0;
    while i < 40000 {
        if self_int(0) != gen { return; }
        i = i + 1;
        sh_angle(0, b, 0deg);                  // 2055
        sh_fire(0);
        b = b + 3deg;                          // 2067 +0.05236
        if rank == 0 { b = b + 3deg; }         // 2069 Easy-only extra step
        k = 0;
        while k < w {
            wait(1);
            k = k + 1;
            if self_int(0) != gen { return; }
        }
        sh_angle(0, c, 0deg);                  // 2079
        sh_fire(0);
        c = c - 3deg;                          // 2091
        if rank == 0 { b = b + 3deg; }         // 2093 Easy-only extra step
        k = 0;
        while k < w {
            wait(1);
            k = k + 1;
            if self_int(0) != gen { return; }
        }
    }
}

// 2108-2151 BossCard7_at3: 6-bullet mode-5 ring with a fresh random base each
// wave; bullets decelerate over 90 frames, then re-aim and dash at the player.
async sub at3(gen: int) {
    var rank: int = global(GVAR_RANK);
    var target: fx = 2fx;                      // !E 2.0; !N 2.0; !H 2.4; !LO 3.3
    if rank == 2 { target = 2.4fx; }
    if rank >= 3 { target = 3.3fx; }
    var w: int = 120;                          // !E 240; !N 120; !H 120; !LO 60
    if rank == 0 { w = 240; }
    if rank >= 3 { w = 60; }
    sh_reset(0);
    sh_sprite(0, TH16_BIG_BALL, 3);            // etSprite(2, 18, 3)
    sh_ring(0, 1);                             // etAim 5: fixed ring, half-way offset
    sh_aim(0, 0);
    sh_count(0, 6, 1);
    sh_speed(0, 2fx, 0fx);                     // etSpeed 2.0, 0.2; 1 layer -> 2.0
    sh_dist(0, -8fx);                          // ANIM entry: -4 * initial speed 2.0
    sh_xform(0, STEP_AIM(target));             // etEx2 STEP a=90 b=1 c=1 r=0
    _ = rand(65536);                           // 2129 %B = %RANDRAD (unused)
    var i: int = 0;
    var k: int = 0;
    var ra: int = 0;
    while i < 40000 {
        if self_int(0) != gen { return; }
        i = i + 1;
        ra = rand(65536) - 32768;              // RANDRAD, -pi..pi
        sh_angle(0, (ra + 5461) as angle, 0deg);   // mode 5: + pi/6 (32768/6)
        sh_fire(0);
        k = 0;
        while k < w {
            wait(1);
            k = k + 1;
            if self_int(0) != gen { return; }
        }
    }
}

// 2153-2195 BossCard7_at4: one mode-5 ring of shards every 90 frames,
// accelerating from 0.1 along each bullet's own direction.
async sub at4(gen: int) {
    var rank: int = global(GVAR_RANK);
    var n: int = 48;                           // !E 24; !N 48; !H 48; !LO 48
    if rank == 0 { n = 24; }
    var target: fx = 3fx;                      // !E 3.0; !N 3.0; !H 3.5; !LO 4.0
    if rank == 2 { target = 3.5fx; }
    if rank >= 3 { target = 4fx; }
    sh_reset(0);
    sh_sprite(0, TH16_SHARD, 8);               // etSprite(3, 10, 8)
    sh_ring(0, 1);                             // etAim 5
    sh_aim(0, 0);
    sh_count(0, n, 1);
    sh_speed(0, 0.1fx, 0fx);                   // etSpeed 0.1, 0.2; 1 layer -> 0.1
    sh_dist(0, -0.4fx);                        // ANIM entry: -4 * initial speed 0.1
    sh_angle(0, 90deg + (32768 / n) as angle, 0deg);  // mode 5: alpha + pi/N
    sh_xform(0, VEL_RAMP(target));             // VELTIME a=60
    _ = rand(65536);                           // 2183 %B = %RANDRAD (unused)
    var i: int = 0;
    var k: int = 0;
    while i < 400000 {
        if self_int(0) != gen { return; }
        i = i + 1;
        sh_fire(0);
        k = 0;
        while k < 90 {
            wait(1);
            k = k + 1;
            if self_int(0) != gen { return; }
        }
    }
}
